package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.graphics.Rect;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.SeekBar;
import android.widget.TextView;
import android.widget.ImageView;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Native configuration and injected accelerometer callbacks only; hardware port is never created. */
public class MotionConfigurationFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private MotionSensorActivity activity;
    private static final class Fake implements MotionPort {boolean available=true,fail;int closes;long time;Sink sink;public boolean available(){return available;}public boolean begin(Sink target){if(fail)throw new IllegalStateException("Injected registration failure");sink=target;return available;}public void close(){closes++;sink=null;}public long now(){return time;}void emit(long time,float x){this.time=time;assertNotNull(sink);sink.sample(time,x,0,9.81f,3);}}
    private void launch()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(MotionSensorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,MotionSensorActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Injected motion samples · no hardware").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(MotionSensorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text("Use this sensor")),5000));}
    private void recreate()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(MotionSensorActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(MotionSensorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text("Use this sensor")),5000));}
    private void finish()throws Exception{MotionSensorActivity closing=activity;i.runOnMainSync(closing::finish);long until=SystemClock.elapsedRealtime()+5000;boolean[] done={false};while(!done[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->done[0]=closing.isDestroyed());if(!done[0])SystemClock.sleep(50);}assertTrue(done[0]);}
    private SeekBar slider(View view){if(view instanceof SeekBar)return (SeekBar)view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int n=0;n<group.getChildCount();n++){SeekBar found=slider(group.getChildAt(n));if(found!=null)return found;}}return null;}
    private View named(View root,String name){if(name.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())||root instanceof TextView text&&name.contentEquals(text.getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=named(group.getChildAt(n),name);if(found!=null)return found;}return null;}
    private View kind(View root,Class<?> type){if(type.isInstance(root))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=kind(group.getChildAt(n),type);if(found!=null)return found;}return null;}
    private void full(View view,String name,boolean action){assertNotNull(name,view);Rect visible=new Rect();assertTrue(name,view.isAttachedToWindow()&&view.isShown()&&view.getGlobalVisibleRect(visible));assertEquals(name+" width",view.getWidth(),visible.width());assertEquals(name+" height",view.getHeight(),visible.height());if(action)assertTrue(name+" touch target",visible.width()>=Design.dp(c,48)&&visible.height()>=Design.dp(c,48));}
    private void completeMotion(View root){
        full(named(root,"Motion sensor"),"Motion title",false);full(kind(root,ImageView.class),"Generated handset artwork",false);
        full(kind(root,MotionSignalChart.class),"Full rolling motion chart",false);full(named(root,"Motion signal scale"),"Visible current scale",false);
        full(slider(root),"Full sensitivity rail",true);full(named(root,"About motion sensitivity"),"Sensitivity information",true);
        View calibration=named(root,"Surface calibration");while(calibration!=null&&!calibration.isClickable())calibration=calibration.getParent() instanceof View?(View)calibration.getParent():null;
        full(calibration,"Surface calibration action",true);full(named(root,"Test again"),"Test action",true);full(named(root,"Use this sensor"),"Use action",true);
        for(String message:List.of("Movement readings received.","Waiting for motion readings. Missing data stays blank.","Motion settings changed elsewhere. Reopen before saving.","No accelerometer is available on this device.","The motion sensor could not start. Try again.")){View status=named(root,message);if(status!=null)full(status,"Complete motion feedback",false);}
    }
    private void capture(String suffix)throws Exception{long until=SystemClock.elapsedRealtime()+5000;CountDownLatch frame=new CountDownLatch(1);boolean[] registered={false};while(!registered[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{if(activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()){View decor=activity.getWindow().getDecorView();if(decor.isAttachedToWindow()&&decor.isHardwareAccelerated()&&decor.isLaidOut()&&!decor.isLayoutRequested()){completeMotion(decor);decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();registered[0]=true;}}});if(!registered[0])SystemClock.sleep(50);}assertTrue("Focused motion configuration",registered[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"motion-settings-"+suffix+".png")));}
    @Test public void fakeSamplesSettingsPersistLifecycleAndUnsupportedErrorsWithoutHardware()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));Map<String,?> personal=new HashMap<>(Prefs.of(c).getAll());String name="motion-test-"+UUID.randomUUID();SharedPreferences prefs=c.getSharedPreferences(name,0);MotionSettings.Factory oldSettings=MotionSettings.factory;MotionPort.Factory oldPorts=MotionSensorActivity.ports;List<Fake> fakes=new CopyOnWriteArrayList<>();List<Activity> owned=new CopyOnWriteArrayList<>();boolean[] unavailable={false},fail={false};Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){if(a instanceof MotionSensorActivity)owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        try{i.runOnMainSync(()->{MotionSettings.factory=context->prefs;MotionSensorActivity.ports=context->{Fake fake=new Fake();fake.available=!unavailable[0];fake.fail=fail[0];fakes.add(fake);return fake;};});launch();assertTrue(prefs.getAll().isEmpty());Fake first=fakes.get(fakes.size()-1);i.runOnMainSync(()->{first.emit(0,0);for(int n=1;n<=30;n++)first.emit(n*200,(float)Math.sin(n/3d)*.3f);});assertTrue(device.wait(Until.hasObject(By.text("Movement readings received.")),5000));assertTrue(device.hasObject(By.text("Signal detected")));UiObject2 info=device.wait(Until.findObject(By.desc("About motion sensitivity")),3000);assertNotNull(info);assertTrue(info.getVisibleBounds().height()>=Design.dp(c,48));assertTrue(info.getVisibleBounds().width()>=Design.dp(c,48));info.click();assertTrue(device.wait(Until.hasObject(By.textContains("applies to your next recording")),3000));UiObject2 dismiss=device.wait(Until.findObject(By.text("Got it")),3000);assertNotNull("Sensitivity explanation dismiss action",dismiss);dismiss.click();assertTrue(device.wait(Until.gone(By.text("Got it")),3000));assertTrue(prefs.getAll().isEmpty());UiObject2 testAgain=device.wait(Until.findObject(By.text("Test again")),3000);assertNotNull("Focused Test again action after dialog dismissal",testAgain);testAgain.click();assertTrue(device.wait(Until.gone(By.text("Signal detected")),3000));assertTrue(device.hasObject(By.descStartsWith("Motion preview: 0 measured")));i.runOnMainSync(()->{first.emit(6000,0);for(int n=1;n<=30;n++)first.emit(6000+n*200,(float)Math.sin(n/3d)*.3f);});assertTrue(device.wait(Until.hasObject(By.text("Movement readings received.")),3000));capture("ready");i.runOnMainSync(()->{SeekBar control=slider(activity.getWindow().getDecorView());assertNotNull(control);Bundle args=new Bundle();args.putFloat(AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,2);assertTrue(control.performAccessibilityAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),args));});assertTrue(device.wait(Until.hasObject(By.text("High")),5000));capture("changed");recreate();assertNull(first.sink);assertTrue(first.closes>0);i.runOnMainSync(()->assertEquals(2,slider(activity.getWindow().getDecorView()).getProgress()));assertTrue(prefs.getAll().isEmpty());capture("recreated");device.findObject(By.text("Use this sensor")).click();PlanOperations.drain(10000);long until=SystemClock.elapsedRealtime()+5000;while(!activity.isDestroyed()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(activity.isDestroyed());assertEquals(2,MotionSettings.read(prefs).level);assertEquals(Set.of("motionSensitivity"),prefs.getAll().keySet());assertTrue(MotionSettings.load(c).smartWake(900000,1000000,30,.10,2,30));
            launch();i.runOnMainSync(()->assertEquals(2,slider(activity.getWindow().getDecorView()).getProgress()));capture("reopened");assertTrue(prefs.edit().putInt("motionSensitivity",0).commit());device.findObject(By.text("Use this sensor")).click();assertTrue(device.wait(Until.hasObject(By.text("Motion settings changed elsewhere. Reopen before saving.")),5000));recreate();assertTrue(device.wait(Until.hasObject(By.text("Motion settings changed elsewhere. Reopen before saving.")),5000));capture("conflict");assertEquals(0,MotionSettings.read(prefs).level);finish();unavailable[0]=true;launch();assertFalse(device.findObject(By.text("Use this sensor")).isEnabled());assertTrue(device.hasObject(By.text("No accelerometer is available on this device.")));capture("unavailable");finish();unavailable[0]=false;fail[0]=true;launch();assertFalse(device.findObject(By.text("Use this sensor")).isEnabled());assertTrue(device.hasObject(By.text("The motion sensor could not start. Try again.")));capture("error");assertEquals(0,MotionSettings.read(prefs).level);assertEquals(personal,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);finish();String slice=InstrumentationRegistry.getArguments().getString("motionSlice");assertTrue("Unknown Motion slice",slice==null||slice.equals("reference"));if(slice==null)RoomConditionsFixture.verify(i,c,device);
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"motion-settings-failure.png"));device.dumpWindowHierarchy(new File(folder,"motion-settings-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{try{PlanOperations.drain(10000);i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));for(Fake fake:fakes)assertNull(fake.sink);}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->{MotionSettings.factory=oldSettings;MotionSensorActivity.ports=oldPorts;});if(owned.stream().allMatch(Activity::isDestroyed))c.deleteSharedPreferences(name);}}
    }
}
